 return n

def parse_bool(v):
 if v in ('1','t','T','TRUE','true','True'): return True
 if v in ('0','f','F','FALSE','false','False'): return False
 raise ValueError('invalid syntax')

def arguments(args):
 opt={k:d for k,s,t,d in SPEC}; changed=set(); files=[]; i=0
 def store(name,val):
  _,short,typ,_=SPECS[name]
  desc=('-'+short+', ' if short else '')+'--'+name
  try:
   if typ==BOOL: result=parse_bool(val)
   elif typ==INT: result=parse_int(val)
   elif typ=='list':
    result=next(csv.reader([val],strict=True)) if val else []
    if name in changed: result=opt[name]+result
   else: result=val
  except (ValueError,csv.Error) as e:
   if typ in (INT,BOOL):
    method='ParseInt' if typ==INT else 'ParseBool'
    err='strconv.'+method+': parsing '+goquote(val)+': '+str(e)
   else: err=str(e)
   raise ArgumentError('invalid argument '+goquote(val)+' for '+goquote(desc)+' flag: '+err)
