  if a=='--': files.extend(args[i:]);break
  if a.startswith('--'):
   key,sep,val=a[2:].partition('=')
   if key not in SPECS: raise ArgumentError('unknown flag: --'+key)
   typ=SPECS[key][2]
   if not sep:
    if typ==BOOL: val='true'
    elif i>=len(args): raise ArgumentError('flag needs an argument: --'+key)
    else: val=args[i];i+=1
   store(key,val)
  elif a.startswith('-') and a!='-':
   rest=a[1:]
   while rest:
    k,rest=rest[0],rest[1:]
    if k not in SHORT: raise ArgumentError("unknown shorthand flag: '%s' in %s"%(k,a))
    key=SHORT[k];typ=SPECS[key][2]
    if rest.startswith('='): val=rest[1:];rest=''
    elif typ==BOOL: val='true'
    elif rest: val=rest;rest=''
    elif i<len(args): val=args[i];i+=1
    else: raise ArgumentError('flag needs an argument: -'+k)
    store(key,val)
  else: files.append(a)
