# A deliberately small, dependency-free YAML subset: mappings, sequences,
# quoted strings, scalar values and inline lists/maps. It also accepts JSON.
def scalar(s):
 s=s.strip()
 if not s: return None
 if s.startswith('"'):
  try: return json.loads(s)
  except Exception: return s[1:-1].replace('\\t','\t').replace('\\n','\n')
 if s.startswith("'") and s.endswith("'"): return s[1:-1].replace("''", "'")
 if s.lower() in ('true','false'): return s.lower()=='true'
 if s.lower() in ('null','~'): return None
 if re.fullmatch(r'[-+]?\d+',s): return int(s)
 if s.startswith('[') and s.endswith(']'):
  return [scalar(x) for x in re.split(r',(?=(?:[^\"\']|\"[^\"]*\"|\'[^\']*\')*$)',s[1:-1])] if s[1:-1].strip() else []
