def lower_keys(obj):
 if isinstance(obj,dict): return {str(k).lower():lower_keys(v) for k,v in obj.items()}
 if isinstance(obj,list): return [lower_keys(v) for v in obj]
 return obj

def yaml_load(text):
 if text.lstrip().startswith('{'): return lower_keys(json.loads(text))
 lines=[]
 for n,line in enumerate(text.splitlines(),1):
  quote=None;end=len(line)
  for j,c in enumerate(line):
   if c in '\"\'' and (j==0 or line[j-1]!='\\'):
    if quote==c: quote=None
    elif quote is None: quote=c
   if c=='#' and quote is None and (j==0 or line[j-1].isspace()): end=j;break
  line=line[:end].rstrip()
  if not line.strip() or line.strip() in ('---','...'): continue
  lines.append((len(line)-len(line.lstrip()),line.lstrip(),n))
 def block(pos,indent):
  islist=lines[pos][1].startswith('- '); obj=[] if islist else {}
  while pos<len(lines) and lines[pos][0]>=indent:
   ind,s,num=lines[pos]
   if ind!=indent: raise ValueError('yaml: line %s: did not find expected key'%num)
   pos+=1
   if islist:
    if not s.startswith('- '): break
    value=scalar(s[2:]);obj.append(value)
   else:
    if ':' not in s: raise ValueError('yaml: line %s: could not find expected \':\''%num)
    k,v=s.split(':',1);k=k.strip().strip('\"\'').lower()
    value=scalar(v)
    if not v.strip() and pos<len(lines) and lines[pos][0]>ind: value,pos=block(pos,lines[pos][0])
    obj[k]=value
  return obj,pos
