GENERAL_NAMES = {
 'tabwidth':'tab-width','header':'header','alternaterows':'alternate-rows','columnmode':'column-mode',
 'linenumMode'.lower():'line-number','wrapmode':'wrap','columndelimiter':'column-delimiter',
 'columnrainbow':'column-rainbow','columnwidth':'column-width','plainmode':'plain',
 'hscrollwidth':'hscroll-width','skipLines'.lower():'skip-lines','jumpTarget'.lower():'jump-target',
 'sectiondelimiter':'section-delimiter','sectionheader':'section-header','sectionheadernum':'section-header-num',
 'sectionstart':'section-start','hideothersection':'hide-other-section','verticalheader':'vertical-header',
 'headercolumn':'header-column','ruler':'ruler','statusline':'status-line','converter':'converter',
 'caption':'caption','followmode':'follow-mode','followall':'follow-all','followname':'follow-name',
 'followsection':'follow-section','watchinterval':'watch',
}
ROOT_NAMES = {
 'quitsmall':'quit-if-one-screen','iswriteoriginal':'write-original','beforewriteoriginal':'exit-write-before',
 'afterwriteoriginal':'exit-write-after','casesensitive':'case-sensitive','smartcasesensitive':'smart-case-sensitive',
 'regexpsearch':'regexp-search','incsearch':'incsearch','memorylimit':'memory-limit','memorylimitfile':'memory-limit-file',
 'disablemouse':'disable-mouse','disablecolumncycle':'disable-column-cycle','viewmode':'view-mode',
 'setterminaltitle':'set-terminal-title','debug':'debug',
}
def apply_general(opt,general):
 if not isinstance(general,dict): return
 for k,v in general.items():
  if k in GENERAL_NAMES and v is not None: opt[GENERAL_NAMES[k]]=v

def load_configuration(cli,changed):
 import sys
 explicit=cli['config'] or os.environ.get('OV_CONFIG','')
 path=explicit
 if not path:
  root=os.environ.get('XDG_CONFIG_HOME') or os.path.expanduser('~/.config')
  for name in ('config.yaml','config.yml','config.json','config.toml'):
   p=os.path.join(root,'ov',name)
   if os.path.exists(p): path=p;break
 config={}
 if path:
  ext=os.path.splitext(path)[1][1:]
  try:
   if ext not in ('yaml','yml','json','toml','ini','properties'): raise ValueError('Unsupported Config Type '+goquote(ext))
   with open(path,encoding='utf-8') as f: text=f.read()
   try:
    if ext=='json': config=lower_keys(json.loads(text))
    elif ext=='toml':
     import tomllib
     config=lower_keys(tomllib.loads(text))
    else: config=yaml_load(text)
   except Exception as e: raise ValueError('While parsing config: '+str(e))
  except OSError as e: print('failed to read config file: open '+path+': '+e.strerror.lower(),file=sys.stderr)
  except ValueError as e: print('failed to read config file: '+str(e),file=sys.stderr)
 if not isinstance(config,dict): config={}
 opt={k:d for k,s,t,d in SPEC}
 for key,flag in ROOT_NAMES.items():
  if key in config and config[key] is not None: opt[flag]=config[key]
 apply_general(opt,config.get('general'))
 for key in list(ROOT_NAMES)+list(GENERAL_NAMES):
  flag=ROOT_NAMES.get(key,GENERAL_NAMES.get(key))
  for env in ['OV_'+key.upper(),'OV_GENERAL_'+key.upper()]:
   if env in os.environ: opt[flag]=scalar(os.environ[env])
 if cli.get('view-mode'): opt['view-mode']=cli['view-mode']
 modes=config.get('mode') or {}
 if opt.get('view-mode') in modes: apply_general(opt,modes[opt['view-mode']])
 for key in changed: opt[key]=cli[key]
 if opt['raw']: opt['converter']='raw'
 elif opt['align']: opt['converter']='align'
 return opt,config
PY"}

